SELECT "nct", "author", "year", "pubmed_id", "trial_phase", "treatment_regimen", "name_of_ici", "class_of_ici", "monotherapy_combination", "type_of_combination", "control_regimen", "type_of_control", "cancer_type", "primary_endpoint", "secondary_endpoint", "clincal_setting_in_relation_to_surgery", "lines_of_treatment", "clinical_setting" FROM public."clinical_trials" WHERE "trial_phase" = 'Phase 2' AND "class_of_ici" = 'PD1' AND "cancer_type" = 'Breast' AND "monotherapy_combination" = 'Yes' AND "type_of_combination" = 'Monotherapy' AND "is_pd_l1_positivity_inclusion_criteria" = 'Yes' AND "is_any_other_biomarker_used_for_inclusion" = 'No' ORDER BY "year" DESC;